  "confidence": 0.85,
  "anomalies": [
    {
      "category": "wrong_value",
      "components": ["C4"],
      "pins": ["C4.1", "C4.2"],
      "nets": ["+3V3", "GND"],
      "observed": "C4, the 3.3 V decoupling capacitor for the U4 thermocouple interface, is valued at 1mF in an 0805 package (C_0805_2012Metric). The SPICE deck models it as 1 mF. The other five decoupling capacitors on the same +3V3 rail in this section are 1uF.",
      "expected": "A 1 µF decoupling capacitor per MAX31855 channel, matching C3, C6 and the other 1uF decoupling parts. A millifarad value cannot be realised in an 0805 footprint, so the value is also physically implausible for this package.",
      "evidence": [
        {"source": "netlist", "quote": "(comp (ref \"C4\") (value \"1mF\") (footprint \"Capacitor_SMD:C_0805_2012Metric\")"},
        {"source": "netlist", "quote": "(comp (ref \"C3\") (value \"1uF\") (footprint \"Capacitor_SMD:C_0805_2012Metric\")"},
        {"source": "spice", "quote": "C4 +3V3 0 1m"},
        {"source": "spec", "quote": "with a 1 µF decoupling cap per channel (`C3` for U2, `C6` for U3, `C4` for U4 — exact mapping per schematic placement)."}
      ],
      "impact": "The U4 channel's supply is decoupled by a part of the wrong value or an impossible package/value combination. The board may be unbuildable as specified, or the wrong-value part may be fitted, leaving U4 (and therefore CS2 zone readings) with inadequate local decoupling for its SPI-based measurements.",
      "confidence": 0.85
    }
  ],
  "summary": "The design is largely consistent with the specification, but C4 is valued at 1mF in an 0805 package where the spec and sibling decoupling capacitors call for 1uF, which is a clear wrong-value anomaly on the U4 thermocouple supply decoupling."
}

